contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint v) public payable {
        c.depositsCount(); if (__ESBMC_reverted()) return;

        uint cBefore = address(c).balance;
        uint countBefore = c.depositsCount(); if (__ESBMC_reverted()) return;
        bool reverted;
        c.withdraw(v); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        uint cAfter = address(c).balance;
        uint countAfter = c.depositsCount(); if (__ESBMC_reverted()) return;

        assert(
            countAfter == countBefore &&
            (reverted
                ? (cAfter == cBefore && countAfter == countBefore)
                : (cBefore >= v && cAfter == cBefore - v && countAfter == countBefore)
            )
        );
    }
}

