pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 v) internal {
        try c.depositsCount() {} catch { return; }
        uint cBefore = address(c).balance;
        uint256 countBefore;
        try c.depositsCount() returns (uint256 __r) { countBefore = __r; } catch { return; }
        bool reverted;
        try c.withdraw(v) { reverted = false; } catch { reverted = true; }
        uint cAfter = address(c).balance;
        uint256 countAfter;
        try c.depositsCount() returns (uint256 __r) { countAfter = __r; } catch { return; }
        assertTrue(countAfter == countBefore &&
            (reverted
                ? (cAfter == cBefore && countAfter == countBefore)
                : (cBefore >= v && cAfter == cBefore - v && countAfter == countBefore)
            ));
    }

    function testFuzz_run(uint256 v) public {
        _run(v);
    }

    receive() external payable {}
}
